package main

import (
	"os"
	"path/filepath"
)

// The starter artifacts (D36 files, S5 posture). The clock and HSB containers
// and the built-in theme are committed artifacts under starter/, generated by
// tools/make_factory_apps.py and tools/make_seed_theme.py and pinned fresh by
// tools/host_orbapp_install_test.py's --check re-run. They reach a card the way
// every third-party file does: the operator copies them. S5 deleted the hub's
// embedded copy (//go:embed seed), the POST /api/orb/seed door, and the
// join-time auto-seed with this sentence left standing where the button was.
//
// What the hub still answers is *freshness*: the Themes face asks Client.
// Containers whether the orb's installed container matches the first-party
// bytes this hub would ship, and that question can only be answered from the
// artifacts on disk beside the source tree. A hub with no readable starter
// files answers nil — no opinion, never a fake "up to date".

// starterDirRel is the artifact directory, joined onto the resolved clone root
// the same way the Theme Editor joins its composer dir.
var starterDirRel = filepath.Join("tools", "orb-manager", "starter")

// starterAppFiles names the first-party containers the resolver answers for.
// The order carries no meaning here (the seed's shipping order died with the
// route); this is a lookup table.
var starterAppFiles = map[string]string{
	"clock":        "clock.orbapp",
	"color_picker": "color_picker.orbapp",
}

// starterContainerFor reads one first-party container's bytes from the starter
// dir. It returns (nil, nil) — the caller's "no copy, no opinion" — for an
// unknown slug, for no resolved repo dir, and for a file that is simply not
// there. Other read errors are real and reported.
func starterContainerFor(repoDir, slug string) ([]byte, error) {
	name, known := starterAppFiles[slug]
	if !known || repoDir == "" {
		return nil, nil
	}
	b, err := os.ReadFile(filepath.Join(repoDir, starterDirRel, name))
	if os.IsNotExist(err) {
		return nil, nil
	}
	return b, err
}
